describe('ChatOrchestrator hooks', () => {
  describe('beforeSession', () => {
    it('called before anything else', async () => {
      const callOrder: string[] = [];
      const hooks = recordingHooks(callOrder, ['beforeSession', 'beforeUserInput', 'beforeModelResponse']);

      const orchestrator = createChatOrchestrator(createMockProvider('hi'), promptBuilder, undefined, {hooks});
      await orchestrator.processMessage(createSession('hello'));

      expect(callOrder[0]).toBe('beforeSession');
    });

    it('fires onError and afterSession in order without calling the provider when it throws', async () => {
      const callOrder: string[] = [];
      let providerCalls = 0;
      const baseProvider = createMockProvider('hi');
      const provider: AIProvider = {
        ...baseProvider,
        async *sendMessage(params: SendMessageParams): AsyncGenerator<MessageChunk> {
          providerCalls++;
          yield* baseProvider.sendMessage(params);
        },
      };
      let receivedSession: ChatSession | undefined;
      let receivedError: Error | undefined;
      const sessionError = new Error('session setup failed');
      const hooks: OrchestratorHooks = {
        ...recordingHooks(callOrder, ['beforeUserInput', 'afterSession']),
        beforeSession: async () => {
          throw sessionError;
        },
        onError: async (currentSession, error) => {
          callOrder.push('onError');
          receivedSession = currentSession;
          receivedError = error;
        },
      };

      const session = createSession('hello');
      const orchestrator = createChatOrchestrator(provider, promptBuilder, undefined, {hooks});
      const outcome = await outcomeOf(orchestrator.processMessage(session));

      expect({
        outcome,
        callOrder,
        providerCalls,
        sameSession: receivedSession === session,
        sameError: receivedError === sessionError,
      }).toEqual({
        outcome: 'session setup failed',
        callOrder: ['onError', 'afterSession'],
        providerCalls: 0,
        sameSession: true,
        sameError: true,
      });
    });
  });

